package tw.sungo.config;
import tw.sungo.model.*; import tw.sungo.repo.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder; import java.time.LocalDate; import java.util.Map;
@Configuration public class SeedData {
 @Bean CommandLineRunner seed(AdminUserRepository users,ProductRepository products,NewsRepository news,SettingRepository settings,PasswordEncoder encoder,@Value("${app.admin-username}") String username,@Value("${app.admin-password}") String password){return args->{
  if(users.findByUsername(username).isEmpty()){AdminUser u=new AdminUser();u.setUsername(username);u.setPasswordHash(encoder.encode(password));users.save(u);}
  if(products.count()==0){String[][] rows={{"喇叭防磁蓋","喇叭零件","適用於音響與喇叭相關產品之防磁蓋，提供穩定品質與客製化合作。","/assets/product-p1-001.jpg","P-01"},{"音響週邊零件","音響零件","音響設備周邊零件，可依圖面與需求評估製作。","/assets/product-p2-001.jpg","P-02"},{"塑膠射出成型","塑膠射出","塑膠射出成型及相關零件加工服務，歡迎洽詢開發需求。","/assets/product-p3-002.jpg","P-03"},{"CNC 車床加工","精密加工","依客戶規格與圖面進行精密加工，支援多樣化零件需求。","/assets/product-p4-001.jpg","P-04"},{"沖模與模具製造","模具製造","沖模與模具製造相關服務，從需求討論到生產配合。","/assets/product-p5-001.jpg","P-05"},{"專利產品與創新設計","專利產品","公司歷年開發之專利與創新產品，提供合作開發洽談。","/assets/product-pa1-001.jpg","IP-01"}};int i=0;for(String[] r:rows){Product p=new Product();p.setName(r[0]);p.setCategory(r[1]);p.setDescription(r[2]);p.setImageUrl(r[3]);p.setCode(r[4]);p.setSortOrder(i++);p.setPublished(true);products.save(p);}}
  if(news.count()==0){NewsArticle n=new NewsArticle();n.setTitle("歡迎洽詢三葛工業產品與加工服務");n.setSummary("如需產品型錄、客製加工或合作資訊，歡迎透過聯絡表單與我們聯繫。");n.setContent("三葛工業提供喇叭防磁蓋、音響週邊零件、塑膠射出、CNC 車床加工與模具製造相關服務。歡迎提供圖面或需求，與我們討論合作可能。");n.setPublishedDate(LocalDate.now());n.setPublished(true);news.save(n);}
  Map.of("companyName","三葛工業股份有限公司","companyNameEn","SUN GO INDUSTRY CO., LTD.","address","新北市樹林區備內街150號","phone","886-2-26886097","fax","886-2-26888227","email","sungo@ms12.hinet.net","intro","專業生產喇叭防磁蓋、音響週邊零件、塑膠射出、CNC 車床加工及各種沖模製造。","businessHours","週一至週五 08:30–17:30").forEach((k,v)->{if(!settings.existsById(k))settings.save(new SiteSetting(k,v));});
 };}
}
